COMMENT ON COLUMN cage_alcohol_questionnaire_grade_flag.cage_alcohol_questionnaire_grade_id IS
    'Foreign key to the parent grade.';
COMMENT ON COLUMN cage_alcohol_questionnaire_grade_flag.flag_id IS
